INSERT INTO `bd_serie` (`ID_SERIE`, `NOM`, `ID_GENRE`, `NOTE`, `FLG_FINI`, `NB_TOME`, `NB_NOTE`, `TRI`, `HISTOIRE`) VALUES
(5580, 'Les contes de l\'Ankou', 70, 8, '0', 3, 2, 'Con', 'Dans cette nouvelle série, les auteurs des « Contes du Korrigan » dévoilent un autre aspect de la Bretagne légendaire… Délaissant un temps les landes fleuries du petit peuple et les joyeux accords de la gavotte, ils s’aventurent, au son d’une marche funèbre, sur les sentiers brumeux des âmes perdues…'),
