INSERT INTO `bd_serie` (`ID_SERIE`, `NOM`, `ID_GENRE`, `NOTE`, `FLG_FINI`, `NB_TOME`, `NB_NOTE`, `TRI`, `HISTOIRE`) VALUES
(7797, 'Rainbow', 52, NULL, '0', 22, 0, 'Rai', 'Prévue en 22 tomes\r\nOn les surnomme Anchan, Joe, Mario, Suppon, Baremoto, Biceps et Chou-Fleur.\r\nCe sont sept adolescents qui, en cette année 1955, vont devoir apprendre à cohabiter ensemble dans la même cellule de la maison de correction de Shio.\r\nPrisonniers d\'un enfer dont les barreaux sont constitués d\'acier mais aussi de souffrance et d\'humiliation, ils attendent qu\'une lueur d\'espoir apparaisse dans ce monde carcéral ténébreux, comme un arc-en-ciel qui surgirait après la pluie.'),
(7798, 'Gabrielle B.', 6, NULL, '1', 0, 0, 'Gab', 'Début du XIXème siècle, sur les côtes de la Manche, une jeune femme corsaire de la République, Gabrielle Baubriand, tente de déjouer le dernier complot royaliste mené par Cadoudal. Or, elle ne se doute pas que son armateur n\'est autre que l\'assassin de son père mais aussi le traître qui soutient le camp adverse...'),
(7799, 'Ener', 6, NULL, '3', 1, 0, 'Ene', ''),
