(405, 291, 'Boule contre les mini-requins', 0, 232, 26, 3730, 0, 3730, 0, 3730, 0, 'N', 0, NULL, 27, '8.50', 2, ''),
(406, 292, '60 gags de Boule et Bill', 1, 232, 26, 3730, 0, 3730, 0, 3730, 0, 'N', 0, NULL, 460, '6.55', 11, ''),
