(448, 100720, 'Alerte à cap Kennedy', 32, 242, 6, 792, 0, 2034, 0, 2034, 0, 'N', 0, NULL, 187, '5.33', 3, ''),
(449, 100723, 'Le mystère des avions fantômes', 33, 242, 6, 792, 0, 2034, 0, 2034, 0, 'N', 0, NULL, 193, '5.67', 3, '');
