(3169, 1808, 'Le cristal majeur', 1, 60, 40, 1736, 0, 278, 0, 278, 0, 'N', 0, '9.45', 96, '5.75', 4, ''),
(3170, 83746, 'Sur l\'île de la licorne', 2, 60, 40, 1736, 0, 278, 0, 278, 0, 'N', 0, '9.45', 89, '5.50', 4, ''),
