(4761, 3303, 'Le dossier Carnavon', 2, 270, 37, 3255, 0, 1838, 0, 3040, 0, 'N', 0, '6.00', 90, NULL, 0, ''),
(4762, 3304, 'Le mystère du Loch Ness T2', 5, 270, 37, 3255, 0, 1838, 0, 1182, 0, 'N', 0, '6.00', 81, '7.00', 1, ''),
