(5269, 3746, 'Intégrale Les 4 as, Tome 3', 3, 10320, 10, 799, 0, 967, 0, 967, 0, 'O', 0, '15.10', 8, NULL, 0, 'L\'intégrale comprend:\r\nLe dragon des neiges (épuisé depuis longtemps), \r\nLe rallye olympique (1969, épuisé depuis longtemps également),\r\nL\'île du Robinson (1970).\r\n'),
(5270, 3747, 'Intégrale Les 4 as, Tome 4', 4, 10320, 10, 799, 0, 967, 0, 967, 0, 'O', 0, '15.10', 7, NULL, 0, 'L\'intégrale comprend:\r\nLe tyran (1971), \r\nLa ruée vers l\'or (1973), \r\nLe Picasso volé (1974).'),
(5272, 3749, 'Les 4 as et la ruée vers l\'or', 11, 5, 10, 799, 0, 967, 0, 967, 0, 'N', 0, '8.95', 120, '4.00', 1, ''),
(5273, 3750, 'Intégrale Les 4 as, Tome 5', 5, 10320, 10, 799, 0, 967, 0, 967, 0, 'O', 0, '15.10', 10, NULL, 0, 'L\'intégrale comprend:\r\nLa bombe F (1975), \r\nLa saucisse volante (1976),\r\nLe gang des chapeaux blancs (1977)'),
(5274, 3751, 'Intégrale Les 4 as, Tome 6', 6, 10320, 10, 799, 0, 967, 0, 967, 0, 'O', 0, '15.10', 8, NULL, 0, '- Le vaisseau fantôme (1978)\r\n- Le diamant bleu (1979)\r\n- La licorne (1980)\r\n'),
