(6250, 4520, 'Sifflez dans le ballon !', 11, 35, 26, 725, 0, 2356, 0, 2356, 0, 'N', 0, '8.20', 279, '6.00', 4, ''),
(6251, 4521, 'Ris, ô poulet', 12, 35, 26, 725, 0, 2356, 0, 2356, 0, 'N', 0, '8.20', 328, '5.86', 7, ''),
(6252, 4522, 'Un flic flanche', 13, 35, 26, 725, 0, 2356, 0, 2356, 0, 'N', 0, '8.20', 245, '6.00', 2, ''),
(6253, 4523, 'Sauté de poulet', 14, 35, 26, 725, 0, 2356, 0, 2356, 0, 'N', 0, '8.20', 257, '6.00', 2, ''),
