INSERT INTO `bd_tome` (`ID_TOME`, `ID_EDITION`, `TITRE`, `NUM_TOME`, `ID_SERIE`, `ID_GENRE`, `ID_SCENAR`, `ID_SCENAR_ALT`, `ID_DESSIN`, `ID_DESSIN_ALT`, `ID_COLOR`, `ID_COLOR_ALT`, `FLG_INT`, `FLG_TYPE`, `PRIX_BDNET`, `NBR_USER_ID`, `moyenne`, `nb_vote`, `HISTOIRE`) VALUES
(7220, 5392, 'Interro surprise', 1, 1335, 26, 938, 0, 3443, 0, 1862, 0, 'N', 0, '8.54', 311, '7.25', 5, 'Approchez, Mesdames et Messieurs ! Venez découvrir les seuls vrais aventuriers modernes : LES PROFS !\r\n\r\nSuivez le prof d\'histoire débutant, le prof de gym sur-vitaminé, la prof de français sexy, la prof de philo blasé et la prof d\'anglais peau de vache dans leur croisade contre l\'ignorance et le poil dans la main !\r\n\r\nPlus forts que Zorro, plus courageux qu\'indiana Jones et bien moins payés que James Bond, ils pénètrent dans la jungle étouffantes des lycées pour affronter les tribus d\'élèves hostiles. Puis, épuisés, ils se réfugient dans leur oasis : la salle des profs ! là, entre la machine à café en panne et les 150 copies à corriger pour demain, ils refont le monde de l\'éducation et des plans pour les vacances...\r\n\r\nSource : 4ème de couverture'),
(7221, 5393, 'Loto et colles', 2, 1335, 26, 938, 0, 3443, 0, 1862, 0, 'N', 0, '8.54', 278, '6.83', 6, ''),
(7222, 5394, 'Tohu-bahut', 3, 1335, 26, 938, 0, 3443, 0, 1862, 0, 'N', 0, '8.99', 257, '6.75', 4, ''),
