(9394, 7433, 'Escarmouches', 4, 1156, 25, 953, 0, 3563, 0, 3563, 0, 'N', 0, '8.99', 62, '6.00', 3, ''),
(9395, 7434, 'Carnages', 5, 1156, 25, 953, 0, 3563, 0, 3563, 0, 'N', 0, '8.99', 55, '5.50', 2, 'Ninon de Lenclos tente de percer le mystère de sa naissance. Mais nul ne souhaite qu\'un si lourd secret éclate au grand jour... surtout pas Gaston d\'Orléans, l\'oncle du roi. La piste mène à Paris... mais la capitale est aux mains des Frondeurs...'),
(9396, 7435, 'Ninon Secrete Tome 6', 0, 1156, 25, 953, 0, 3563, 0, 3563, 0, 'N', 0, '8.99', 9, NULL, 0, ''),
(9397, 7436, 'Les Vikings en Normandie', 0, 1169, 9, 250, 0, 4105, 0, 4105, 0, 'N', 0, '8.99', 12, NULL, 0, ''),
(9398, 7437, 'Les spectres du tsar', 1, 1175, 39, 2494, 0, 3169, 0, 9769, 0, 'N', 0, '10.99', 64, '8.00', 2, ''),
